// 🔔 監聽金鑰本機更新事件並彈出輕量通知
const handleKeyUpdated = (e: Event) => {
    const customEvent = e as CustomEvent<{ recoveryKey?: string; source?: string }>;
    if (!isUserLoggedIn()) return;
    if (customEvent.detail?.source !== "remote_sync") return;
    toast.info(zh ? "✨ 帳號引繼碼已自其他裝置同步更新" : "✨ Recovery key synced from another device");
};
window.addEventListener("tabiji:recovery_key_updated", handleKeyUpdated);

target_content:
export function isUserLoggedIn(): boolean {
    if (typeof window === "undefined") return false;
    try {
        const hasNicknameAndId = Boolean(localStorage.getItem("user_nickname") && localStorage.getItem(RECOVERY_KEY));
        const hasModernRecoveryKey = Boolean(localStorage.getItem("user_recovery_key"));
        return hasNicknameAndId || hasModernRecoveryKey;
    } catch {
        return false;
    }
}

replacement_content:
export function isUserLoggedIn(): boolean {
    if (typeof window === "undefined") return false;
    try {
        const nickname = localStorage.getItem("user_nickname");
        const hasLegacyId = Boolean(localStorage.getItem(RECOVERY_KEY));
        const hasModernRecoveryKey = Boolean(localStorage.getItem("user_recovery_key"));
        return Boolean(nickname && (hasLegacyId || hasModernRecoveryKey));
    } catch {
        return false;
    }
}

